$body = '{"email":"ivan@example.com","password":"DemoPass123"}'; $r = Invoke-WebRequest -Uri http://127.0.0.1:8000/auth/login -Method Post -ContentType 'application/json' -Body $body -UseBasicParsing; $j = $r.Content | ConvertFrom-Json; $token = $j.access_token; "TOKEN: $token"; $h = @{ Authorization = "Bearer $token"; "Content-Type" = "application/json" }; $oid = "e955e989-dd66-44e5-ab35-fcadce50f1c3"; $g = Invoke-WebRequest -Uri "http://127.0.0.1:8000/admin/orders/$oid" -Method Get -Headers $h -UseBasicParsing; "GET status: $($g.Content)"; $p = Invoke-WebRequest -Uri "http://127.0.0.1:8000/admin/orders/$oid/status" -Method Patch -Headers $h -Body '{"status":"paid"}' -UseBasicParsing; "PATCH paid: $($p.StatusCode) $($p.Content)"; $g2 = Invoke-WebRequest -Uri "http://127.0.0.1:8000/admin/orders/$oid" -Method Get -Headers $h -UseBasicParsing; "GET after patch: $($g2.Content)"
